API_name: english_talking_get_answer
Description:
{
  "description": "This API aims to provide users with the possibility of conducting dialogues in English where the conversations and answers are registered and evaluated by the users themselves.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "status",
      "type": "STRING",
      "description": "approved or analyzing",
      "default": "approved"
    },
    {
      "name": "answer",
      "type": "STRING",
      "description": "Response to the initial speech of the dialogue",
      "default": "Hi, how are you?"
    },
    {
      "name": "_id",
      "type": "STRING",
      "description": "Unique dialog identifier (automatically generated)\n\n",
      "default": "5ec47b3d8958430d6a6d5898"
    },
    {
      "name": "speech",
      "type": "STRING",
      "description": "Speak in which the usuairio wants to get an answer",
      "default": "Hi"
    },
    {
      "name": "user",
      "type": "STRING",
      "description": "User who created the dialogue",
      "default": "5ec479048958430d6a6d5895"
    }
  ]
}

